async function chamarServicoPagamento(carrinho) {
  const circuitBreaker = new CircuitBreaker({
    timeout: 3000,       // Falha se demorar mais de 3s
    errorThreshold: 50,  // Abre o circuito se 50% das requisições falharem
    resetTimeout: 10000  // Tenta reconectar após 10s
  });

  return await circuitBreaker.execute(async () => {
    return await http.post('/api/v1/pagamentos', carrinho);
  });
}
